import { CSSProperties } from 'react';

export const colors: {
  background: string;
  surface: string;
  text: string;
  muted: string;
  primary: string;
  border: string;
} = {
  background: '#f8fafc',
  surface: '#ffffff',
  text: '#0f172a',
  muted: '#64748b',
  primary: '#2563eb',
  border: '#e2e8f0',
};

export const layout: {
  page: CSSProperties;
  section: CSSProperties;
  container: CSSProperties;
  grid: CSSProperties;
} = {
  page: {
    minHeight: '100vh',
    backgroundColor: colors.background,
    color: colors.text,
    fontFamily:
      'Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
    margin: 0,
  },
  section: {
    padding: '48px 24px',
  },
  container: {
    width: '100%',
    maxWidth: '1120px',
    margin: '0 auto',
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))',
    gap: '24px',
  },
};

export function cardStyle(highlighted?: boolean): CSSProperties {
  return {
    backgroundColor: colors.surface,
    border: `1px solid ${highlighted ? colors.primary : colors.border}`,
    borderRadius: '16px',
    padding: '24px',
    boxShadow: highlighted
      ? '0 12px 32px rgba(37, 99, 235, 0.16)'
      : '0 10px 24px rgba(15, 23, 42, 0.08)',
    color: colors.text,
    transition: 'transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease',
  };
}

